add_filter( 'authenticate', 'perfectpixel_generic_login_error', 99 );
add_filter( 'shake_error_codes', 'perfectpixel_generic_login_error_shake' );

function perfectpixel_generic_login_error( $user ) {
	if ( is_wp_error( $user ) && array_intersect( $user->get_error_codes(), array( 'invalid_username', 'invalid_email', 'incorrect_password' ) ) ) {
		return new WP_Error( 'perfectpixel_login_failed', esc_html( '{{login_error_message}}' ) );
	}
	return $user;
}

function perfectpixel_generic_login_error_shake( $codes ) {
	$codes[] = 'perfectpixel_login_failed';
	return $codes;
}
